-- ODMCS | 5,000 synthetic donor cases | Snapshot: 18 November 2026
-- MySQL 8.0. Open in a new Workbench SQL tab and execute the entire file.
-- Requires the project's Donor table and the 25-branch South India hospital directory.
-- Names, birth dates, blood groups, case volumes, certification times and references
-- are generated for coursework. All certificate references begin with SYN-ODMCS-.
-- Hospital links simulate case registration. Contact_Number remains NULL.
USE odmcs;

DROP TEMPORARY TABLE IF EXISTS donor_seed_branches, donor_seed_mapping, donor_seed_cases;
CREATE TEMPORARY TABLE donor_seed_branches (
    Branch_Key INT PRIMARY KEY,
    Hospital_Name VARCHAR(150) NOT NULL,
    City VARCHAR(100) NOT NULL,
    State VARCHAR(32) NOT NULL
);

CREATE TEMPORARY TABLE donor_seed_mapping AS
SELECT b.Branch_Key, MIN(h.Hospital_ID) AS Hospital_ID, COUNT(h.Hospital_ID) AS Matches_Found
FROM donor_seed_branches AS b
LEFT JOIN Hospital AS h ON h.Hospital_Name = b.Hospital_Name
                       AND h.City = b.City AND h.State = b.State
GROUP BY b.Branch_Key;

CREATE TEMPORARY TABLE donor_seed_cases (
    Cert_Ref VARCHAR(100) PRIMARY KEY,
    Branch_Key INT NOT NULL,
    Donor_Name VARCHAR(100) NOT NULL,
    Date_of_Birth DATE NOT NULL,
    Gender VARCHAR(30) NOT NULL,
    Blood_Group VARCHAR(3) NOT NULL,
    Certified_At DATETIME NOT NULL,
    Donor_Status VARCHAR(10) NOT NULL
);





















-- Import only when all 25 hospital matches are unambiguous and all cases are staged.
SELECT COUNT(*) INTO @mapped FROM donor_seed_mapping WHERE Matches_Found = 1;
SELECT COUNT(*) INTO @staged FROM donor_seed_cases;
SELECT GET_LOCK('odmcs.synthetic_donor_import_5000', 30) INTO @seed_lock;
START TRANSACTION;
    Donor_Name, Date_of_Birth, Gender, Blood_Group, Hospital_ID,
    Brain_Stem_Death_Cert_Ref, Brain_Stem_Death_Certified_At, Donor_Status
)
SELECT s.Donor_Name, s.Date_of_Birth, s.Gender, s.Blood_Group, m.Hospital_ID,
       s.Cert_Ref, s.Certified_At, s.Donor_Status
FROM donor_seed_cases AS s
JOIN donor_seed_mapping AS m ON m.Branch_Key = s.Branch_Key
LEFT JOIN Donor AS d ON d.Brain_Stem_Death_Cert_Ref = s.Cert_Ref
WHERE d.Donor_ID IS NULL AND @mapped = 25 AND @staged = 5000 AND @seed_lock = 1;
SET @donors_added = ROW_COUNT();
COMMIT;
DO RELEASE_LOCK('odmcs.synthetic_donor_import_5000');

SELECT CASE WHEN @mapped <> 25 THEN 'Check hospital names, missing branches, or duplicates'
            WHEN @staged <> 5000 THEN 'Run the entire SQL file'
            WHEN COALESCE(@seed_lock, 0) <> 1 THEN 'Another import is busy. Run again'
            ELSE 'Complete' END AS Import_Status,
       @donors_added AS Donors_Added,
       COUNT(DISTINCT d.Brain_Stem_Death_Cert_Ref) AS Synthetic_Donors_Present
FROM donor_seed_cases AS s
JOIN Donor AS d ON d.Brain_Stem_Death_Cert_Ref = s.Cert_Ref;

-- A state-level report for the imported cases.
SELECT h.State, COUNT(*) AS Synthetic_Donors
FROM donor_seed_cases AS s
JOIN Donor AS d ON d.Brain_Stem_Death_Cert_Ref = s.Cert_Ref
JOIN Hospital AS h ON h.Hospital_ID = d.Hospital_ID
GROUP BY h.State ORDER BY h.State;

DROP TEMPORARY TABLE donor_seed_branches, donor_seed_mapping, donor_seed_cases;
